package org.apache.commons.cli;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeEach;

import java.lang.reflect.Field;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class OptionsHasShortOptionTest {

    private Options options;

    @BeforeEach
    void setUp() {
        options = new Options();
    }

    // Helper to insert an entry into the private shortOpts map via reflection
    @SuppressWarnings({"rawtypes", "unchecked"})
    private void putShortOption(String key) {
        try {
            Field f = Options.class.getDeclaredField("shortOpts");
            f.setAccessible(true);
            Map map = (Map) f.get(options);
            map.put(key, null); // value can be null; map is raw at runtime
        } catch (ReflectiveOperationException e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    void testHasShortOption_withNullAndEmpty() {
        // Null input - should not throw and should be false when map is empty
        assertDoesNotThrow(() -> {
            boolean res = options.hasShortOption(null);
            assertFalse(res);
        });

        // Empty string input - when not present should be false
        assertFalse(options.hasShortOption(""));

        // Insert empty key and verify true
        putShortOption("");
        assertTrue(options.hasShortOption(""));
    }

    @Test
    void testHasShortOption_singleHyphen_and_doubleHyphen() {
        // single hyphen "-a" -> stripped to "a"
        assertFalse(options.hasShortOption("-a"));
        putShortOption("a");
        assertTrue(options.hasShortOption("-a"));

        // double hyphen "--long" -> stripped to "long"
        assertFalse(options.hasShortOption("--long"));
        putShortOption("long");
        assertTrue(options.hasShortOption("--long"));
    }

    @Test
    void testHasShortOption_noHyphen_and_multipleLeadingHyphens() {
        // no hyphen: "plain" remains "plain"
        assertFalse(options.hasShortOption("plain"));
        putShortOption("plain");
        assertTrue(options.hasShortOption("plain"));

        // three leading hyphens: "---abc" -> stripLeadingHyphens sees "--" and returns "-abc"
        // Put key "-abc" and verify that "---abc" matches it
        assertFalse(options.hasShortOption("---abc"));
        putShortOption("-abc");
        assertTrue(options.hasShortOption("---abc"));
    }

    @Test
    void testHasShortOption_caseSensitivity() {
        // Ensure lookup is case-sensitive: "A" != "a"
        putShortOption("A");
        assertTrue(options.hasShortOption("A"));
        assertFalse(options.hasShortOption("-a"));
    }
}

